    for gid in genes:
        if sums[g]['n'].get(gid):
            ref[g][gid]=sums[g]['sum'][gid]/sums[g]['n'][gid]
# read input col values
inp={g:{} for g in groups}
with gzip.open('/workspace/inputs/sample.swap.rna.q1.tsv.gz','rt') as f:
